UpdateContext(
    {
        locRefreshOverviewList: true,
        locFilterValues: LookUp(
            colFiltersOverview,
            true
        )
    }
);
With(
    {

        baseFiltered: Filter(
            Projects,
            And(
                Or(
                    IsBlank(locFilterValues.ProjectManager),
                    ThisRecord.'Project Manager'.Id = GUID(locFilterValues.ProjectManager.PersonaKey)
                ),
                Or(
                    IsBlank(locFilterValues.Country),
                    ThisRecord.Country.Country = locFilterValues.Country.Country
                ),
                Or(
                    IsBlank(locFilterValues.Area),
                    ThisRecord.'Area/State/Province'.Name = locFilterValues.Area.Name
                ),
                Or(
                    IsBlank(locFilterValues.Technology),
                    ThisRecord.Technology = locFilterValues.Technology.Value
                ),
                Or(
                    IsBlank(locFilterValues.ProjectStatus),
                    ThisRecord.'Cluster State'.'Project State' = locFilterValues.ProjectStatus.'Project State'
                )
            )
        )
    },
    With(
        {
            keywordFiltered: If(
                Or(
                    IsBlank(locFilterValues.ProjectKeyword),
                    Len(locFilterValues.ProjectKeyword) < 3
                ),
                baseFiltered,
                Filter(
                    baseFiltered,
                    Or(
                        locFilterValues.ProjectKeyword in ThisRecord.'Project Name',
                        locFilterValues.ProjectKeyword in ThisRecord.'Project ID',
                        locFilterValues.ProjectKeyword in ThisRecord.'Internal Project ID',
                        locFilterValues.ProjectKeyword in ThisRecord.'Short Name'
                    )
                )
            )
        },
        ClearCollect(
            colFilteredProjects,
            If(
                IsBlank(locFilterValues.Capacity),
                keywordFiltered,
                If(
                    locFilterValues.CapacityOperator = gblAppConstants.FilterOperators.Equals,
                    Filter(
                        keywordFiltered,
                        ThisRecord.'Total Capacity' = Value(locFilterValues.Capacity)
                    ),
                    If(
                        locFilterValues.CapacityOperator = gblAppConstants.FilterOperators.GreaterThan,
                        Filter(
                            keywordFiltered,
                            ThisRecord.'Total Capacity' > Value(locFilterValues.Capacity)
                        ),
                        If(
                            locFilterValues.CapacityOperator = gblAppConstants.FilterOperators.GreaterThanOrEqualTo,
                            Filter(
                                keywordFiltered,
                                ThisRecord.'Total Capacity' >= Value(locFilterValues.Capacity)
                            ),
                            If(
                                locFilterValues.CapacityOperator = gblAppConstants.FilterOperators.LessThan,
                                Filter(
                                    keywordFiltered,
                                    ThisRecord.'Total Capacity' < Value(locFilterValues.Capacity)
                                ),
                                If(
                                    locFilterValues.CapacityOperator = gblAppConstants.FilterOperators.LessThanOrEqualsTo,
                                    Filter(
