                totalRows / pageSize,
                0
            ) + If(
                totalRows = 0,
                1,
                0
            ),
            adjustedPage: If(
                currentPage > Value(
                    RoundUp(
                        totalRows / pageSize,
                        0
                    ) + If(
                        totalRows = 0,
                        1,
                        0
                    )
                ),
                1,
                currentPage
            )
        },
